  if (n <= 8 || (n % 500) == 0)
    MCLA_LOG_INFO("P4'-PRESENT kick #{} dev={:08X} fb={:08X} surf={:08X}",
                  n, dev, fbAddr, mcla::gpu::ResolvedPresentSurfaceVA());

  __imp__sub_824294E0(ctx, base);

