    (void)mem.ReadU32BE(kBlk + 128, &dl128);
    (void)mem.ReadU32BE(kBlk + 132, &dl132);
    (void)mem.ReadU32BE(kBlk + 184, &f184);
    (void)mem.ReadU32BE(kBlk + 188, &f188);
