      (void)memR.ReadU32BE(inner + 0u, &e0);
      (void)memR.ReadU32BE(inner + 4u, &e4);
      (void)memR.ReadU32BE(inner + 16u, &e8);
      (void)memR.ReadU32BE(inner + 20u, &e12);
