        // could never express is on the next line.
        MCLA_LOG_WARN("TOC-DUMP2 parsed wrote={} okread={} entry={:08X} at query #{}",
                      r.wrote ? 1 : 0, r.okRead ? 1 : 0, ctx.r3.u32, n);
