  (void)mem.ReadU32BE(obj + 28, &p28);
  (void)mem.ReadU32BE(obj + 32, &gran);
  (void)mem.ReadU32BE(obj + 8, &wbuf);
  const uint32_t lrWin = static_cast<uint32_t>(ctx.lr);  // BEFORE the call (F-382)
