    uint32_t q24 = 0, q28 = 0, past[6] = {0, 0, 0, 0, 0, 0};
    (void)mem.ReadU32BE(obj + 24, &q24);
    (void)mem.ReadU32BE(obj + 28, &q28);
    for (int i = 0; i < 6; ++i)
      (void)mem.ReadU32BE(obj + 0x28u + static_cast<uint32_t>(i * 4), &past[i]);
    uint32_t sl0 = 0, sl1 = 0;
